(function(E){ const x = E["exam-08"] = E["exam-08"] || {units:{}}; (x.units = x.units || {})["x08-l2"] = {"id":"x08-l2","patterns":["L2-tours","TR-ruledout","TR-paraphrase"],"title":{"en":"Listening Part 2: a guided tour","tr":"Listening Part 2: rehberli bir tur","fa":"Listening Part 2: یک تور راهنمادار"},"objective":{"en":"In this lesson you will learn to follow one speaker giving visitor information: choose the two facts that are really true, and match the parts of a place to what the guide says about each.","tr":"Bu derste ziyaretçilere bilgi veren tek bir konuşanı takip etmeyi öğreneceksin: gerçekten doğru olan iki bilgiyi seçecek ve bir yerin bölümlerini rehberin her biri hakkında söylediğiyle eşleştireceksin.","fa":"در این درس یاد می‌گیری حرف‌های یک گوینده را که به بازدیدکننده‌ها اطلاعات می‌دهد دنبال کنی: دو موردی را که واقعاً درست‌اند انتخاب کنی و بخش‌های یک مکان را با چیزی که راهنما درباره‌ی هرکدام می‌گوید جور کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 2: a guided tour","tr":"Listening Part 2: rehberli bir tur","fa":"Listening Part 2: یک تور راهنمادار"},"objective":{"en":"In this lesson you will learn to follow one speaker giving visitor information: choose the two facts that are really true, and match the parts of a place to what the guide says about each.","tr":"Bu derste ziyaretçilere bilgi veren tek bir konuşanı takip etmeyi öğreneceksin: gerçekten doğru olan iki bilgiyi seçecek ve bir yerin bölümlerini rehberin her biri hakkında söylediğiyle eşleştireceksin.","fa":"در این درس یاد می‌گیری حرف‌های یک گوینده را که به بازدیدکننده‌ها اطلاعات می‌دهد دنبال کنی: دو موردی را که واقعاً درست‌اند انتخاب کنی و بخش‌های یک مکان را با چیزی که راهنما درباره‌ی هرکدام می‌گوید جور کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"1"},{"label":{"en":"Options in the box","tr":"Kutudaki seçenek","fa":"گزینه‌های کادر"},"value":"A-H"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a cricket ground","tr":"Bu sınav: bir kriket sahası","fa":"این آزمون: یک زمین کریکت"},"intro":{"en":"Tours and visitor information are the most frequent Part 2 situation: a guide shows a group round a building, a park or a site. The talk moves through the place in order, so the questions do too.","tr":"Turlar ve ziyaretçi bilgileri Part 2’de en sık çıkan durumdur: bir rehber bir grubu bir binada, bir parkta ya da bir alanda gezdirir. Konuşma yerin içinde sırayla ilerler, sorular da öyle.","fa":"تور و اطلاعات بازدیدکننده پرتکرارترین موقعیت Part 2 است: یک راهنما گروهی را در یک ساختمان، پارک یا محوطه می‌گرداند. صحبت به ترتیبِ مسیر جلو می‌رود و سؤال‌ها هم همین‌طور."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x08-l2-ctx","exam":true,"patterns":["L2-tours"],"often":{"pattern":"L2-tours","n":13,"of":40,"label":{"en":"Comes up often in the real exam: 13 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 13’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۳ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A guided tour of a sports ground","tr":"Bir spor sahasında rehberli tur","fa":"تور راهنمادار یک ورزشگاه"},"asks":{"en":"A guide welcomes a group, explains what the tour includes and what is not allowed, gives some practical information about coming back for a match, and then tells the story of several parts of the ground as the group walks past them.","tr":"Bir rehber grubu karşılıyor, turun neleri kapsadığını ve nelere izin verilmediğini anlatıyor, bir maça tekrar gelmek isteyenlere pratik bilgiler veriyor ve sonra grup yürürken sahanın birkaç bölümünün hikâyesini anlatıyor.","fa":"یک راهنما از گروه استقبال می‌کند، توضیح می‌دهد تور شامل چه چیزهایی است و چه کارهایی مجاز نیست، برای کسانی که می‌خواهند برای تماشای مسابقه برگردند اطلاعات عملی می‌دهد و بعد، وقتی گروه راه می‌رود، داستان چند بخش ورزشگاه را تعریف می‌کند."},"fields":["What the tour includes","Rules for visitors","Tickets and prices","Parts of the ground and their history"],"words":[{"a":"not possible","b":"I’m afraid you can’t / that’s not allowed","tr":"mümkün değil","fa":"ممکن نیست"},{"a":"behind the scenes","b":"the areas visitors don’t normally see","tr":"perde arkası","fa":"پشت صحنه"},{"a":"step-free","b":"no stairs / suitable for wheelchairs","tr":"basamaksız","fa":"بدون پله"},{"a":"free","b":"get in for nothing / no charge","tr":"ücretsiz","fa":"رایگان"},{"a":"go on sale","b":"you can buy them from","tr":"satışa çıkmak","fa":"به فروش گذاشته شدن"},{"a":"the oldest","b":"it was here first / nothing else is as old","tr":"en eski","fa":"قدیمی‌ترین"},{"a":"copied","b":"others built one just like it","tr":"taklit edilmiş","fa":"از رویش ساخته‌اند"},{"a":"no longer used","b":"just stands there now / a reminder of the old days","tr":"artık kullanılmıyor","fa":"دیگر استفاده نمی‌شود"},{"a":"came from","b":"it originally hung / was brought here from","tr":"... yerden geldi","fa":"از جای دیگری آمده"},{"a":"paid for by","b":"the money came from / people gave","tr":"parası ... tarafından ödendi","fa":"هزینه‌اش را ... داد"},{"a":"damaged","b":"destroyed / brought down","tr":"hasar görmüş","fa":"آسیب‌دیده"},{"a":"repaired","b":"back in use / restored","tr":"onarılmış","fa":"تعمیرشده"}],"traps":[{"en":"Something visitors want is mentioned and then refused: \"I know you were hoping to see the kitchens, but they’re closed today.\" It is not part of the tour.","tr":"Ziyaretçilerin istediği bir şeyden söz edilip geri çevrilir: \"Mutfakları görmek istediğinizi biliyorum ama bugün kapalı.\" Bu, turun parçası değildir.","fa":"از چیزی که بازدیدکننده‌ها می‌خواهند حرف زده می‌شود و بعد رد می‌شود: «می‌دانم دلتان می‌خواست آشپزخانه را ببینید، اما امروز بسته است». این جزء تور نیست."},{"en":"A belief is corrected: \"People think the café is for members only, but anyone can use it.\" The answer is what is true now.","tr":"Bir inanış düzeltilir: \"İnsanlar kafenin yalnızca üyelere açık olduğunu sanıyor ama herkes kullanabilir.\" Cevap şu an doğru olandır.","fa":"یک تصور اصلاح می‌شود: «مردم فکر می‌کنند کافه فقط مال اعضاست، اما همه می‌توانند از آن استفاده کنند». جواب چیزی است که الان درست است."},{"en":"In the box task the guide may say a lot about one place. Match only the idea in the box that is really stated about it.","tr":"Kutulu görevde rehber bir yer hakkında çok şey söyleyebilir. Yalnızca kutudaki fikirlerden o yer için gerçekten söyleneni eşleştir.","fa":"در تمرین کادر، راهنما ممکن است درباره‌ی یک جا زیاد حرف بزند. فقط ایده‌ای از کادر را جور کن که واقعاً درباره‌ی همان جا گفته شده."}],"example":{"lines":[["Guide","The fountain in the square looks very old, but it was only put there in 1990. The stone came from a church that was knocked down."]],"item":"What does the guide say about the fountain? A It is the oldest object in the square.  B It is made from material that was used before.","answer":"B","why":{"en":"\"Looks very old, but\" rules out A. \"The stone came from a church\" = material used before.","tr":"\"Çok eski görünüyor ama\" A’yı eler. \"Taş bir kiliseden geldi\" = daha önce kullanılmış malzeme.","fa":"«خیلی قدیمی به نظر می‌رسد، اما» A را رد می‌کند. «سنگش از یک کلیسا آمده» یعنی ماده‌ای که قبلاً استفاده شده."}}},{"id":"L2-tours","ctx":["L2-tours"],"title":{"en":"Tours and visitor information","tr":"Turlar ve ziyaretçi bilgileri","fa":"تورها و اطلاعات بازدیدکننده"},"asks":{"en":"A guide or presenter tells visitors about a place: a heritage walk, a castle, a museum, a stadium, a boat trip. Questions ask about its history, what is new, what visitors can do, the rules and what the guide recommends.","tr":"Bir rehber ya da sunucu ziyaretçilere bir yeri anlatır: tarihî bir yürüyüş, bir kale, bir müze, bir stadyum, bir tekne gezisi. Sorular yerin tarihini, yeniliklerini, ziyaretçilerin neler yapabileceğini, kuralları ve rehberin tavsiyesini sorar.","fa":"یک راهنما یا مجری جایی را برای بازدیدکننده‌ها معرفی می‌کند: یک پیاده‌روی تاریخی، یک قلعه، یک موزه، یک ورزشگاه، یک گردش با قایق. سؤال‌ها درباره‌ی تاریخچه، چیزهای تازه، کارهایی که بازدیدکننده می‌تواند بکند، قانون‌ها و توصیه‌ی راهنماست."},"fields":["What was the building originally used for?","What has changed recently?","What does the guide recommend?","Which TWO activities are available today?","What are visitors not allowed to do?","What can visitors see in each area?"],"words":[{"a":"originally built as","b":"it started life as","tr":"aslen ... olarak yapılmış","fa":"در اصل به‌عنوان ... ساخته شده"},{"a":"restored","b":"brought back to how it looked","tr":"restore edilmiş","fa":"مرمت‌شده"},{"a":"exhibition","b":"the display / what's on show","tr":"sergi","fa":"نمایشگاه"},{"a":"not allowed","b":"please don't / you can't","tr":"yasak","fa":"ممنوع"},{"a":"recommend","b":"if you only have time for one thing","tr":"tavsiye etmek","fa":"توصیه کردن"},{"a":"recently opened","b":"it's only been open since","tr":"yeni açılmış","fa":"تازه باز شده"},{"a":"guided","b":"someone will take you round","tr":"rehberli","fa":"با راهنما"},{"a":"free","b":"it won't cost you anything","tr":"ücretsiz","fa":"رایگان"},{"a":"closed for repairs","b":"work is being done on","tr":"onarım için kapalı","fa":"به‌خاطر تعمیر بسته"},{"a":"souvenirs","b":"things to take home","tr":"hediyelik eşya","fa":"سوغاتی"},{"a":"most popular","b":"what people enjoy most","tr":"en popüler","fa":"پرطرفدارترین"},{"a":"the view","b":"you can see right across","tr":"manzara","fa":"منظره"}],"traps":[{"en":"Past and present: \"this was once the stables; today it’s the cafe\". The question usually asks about now.","tr":"Geçmiş ve şimdi: \"burası eskiden ahırdı; bugün kafe\". Soru genelde şimdiyi sorar.","fa":"گذشته و حال: «اینجا قبلاً اصطبل بود؛ امروز کافه است». سؤال معمولاً درباره‌ی حالاست."},{"en":"Every option is mentioned; one is \"temporarily closed\" or \"coming next year\".","tr":"Her seçenek söylenir; biri \"geçici olarak kapalı\" ya da \"gelecek yıl geliyor\" olur.","fa":"همه‌ی گزینه‌ها گفته می‌شوند؛ یکی «موقتاً بسته» است یا «سال آینده می‌آید»."},{"en":"Choose TWO: three activities are named, but one is only for groups or children.","tr":"İki seçenek seç: üç etkinlik sayılır ama biri yalnızca gruplar ya da çocuklar içindir.","fa":"انتخاب دو گزینه: سه فعالیت گفته می‌شود، ولی یکی فقط برای گروه‌ها یا بچه‌هاست."}],"example":{"lines":[["Guide","Many visitors head straight for the tower, and the view from the top is lovely."],["Guide","But if you only have time for one thing, I’d say go to the kitchens."],["Guide","They’re the oldest part of the castle and still have the original ovens."]],"item":"What does the guide recommend?  A the tower   B the kitchens   C the gardens","answer":"B","why":{"en":"The tower is popular, but \"if you only have time for one thing, I’d say\" introduces the recommendation: the kitchens.","tr":"Kule popüler ama \"if you only have time for one thing, I’d say\" tavsiyeyi getiriyor: mutfaklar.","fa":"برج پرطرفدار است، ولی «if you only have time for one thing, I’d say» توصیه را معرفی می‌کند: آشپزخانه‌ها."}},"general":true,"patterns":["L2-tours"],"often":{"pattern":"L2-tours","n":13,"of":40,"label":{"en":"Comes up often in the real exam: 13 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 13’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۳ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Two pairs, then a box of eight","tr":"İki çift, sonra sekizli bir kutu","fa":"دو جفت سؤال، بعد یک کادر هشت‌تایی"},"body":{"en":"Questions 11-12 and 13-14: choose TWO letters from A-E each time. Questions 15-20: match six places to a box of eight ideas, A-H, using each letter once. The talk follows the order of the questions, with a short pause before Question 15.","tr":"Soru 11-12 ve 13-14: her seferinde A-E arasından İKİ harf seç. Soru 15-20: altı yeri sekiz fikirlik bir kutuyla (A-H) eşleştir, her harfi bir kez kullan. Konuşma soruların sırasını izler; Soru 15’ten önce kısa bir ara vardır.","fa":"سؤال‌های ۱۱-۱۲ و ۱۳-۱۴: هر بار دو حرف از A تا E انتخاب کن. سؤال‌های ۱۵ تا ۲۰: شش مکان را با یک کادر هشت‌تایی (A تا H) جور کن و هر حرف را یک بار به کار ببر. صحبت به ترتیب سؤال‌ها جلو می‌رود و قبل از سؤال ۱۵ یک مکث کوتاه هست."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"For choose TWO, read the question line closely: \"on the tour\" is not the same as \"at the ground\".","tr":"İKİ seçmeli sorularda soru satırını dikkatle oku: \"on the tour\" ile \"at the ground\" aynı şey değil.","fa":"در سؤال‌های «دو تا انتخاب کن» خط سؤال را دقیق بخوان: «on the tour» با «at the ground» یکی نیست."},{"en":"Tick an option only when it is confirmed; cross it out when you hear \"I’m afraid\", \"not any more\" or \"not until\".","tr":"Bir seçeneği ancak doğrulandığında işaretle; \"I’m afraid\", \"not any more\" ya da \"not until\" duyduğunda üstünü çiz.","fa":"گزینه را فقط وقتی تأیید شد علامت بزن؛ وقتی «I’m afraid»، «not any more» یا «not until» شنیدی خطش بزن."},{"en":"Before Question 15, read the eight ideas and say each one in your own words.","tr":"Soru 15’ten önce sekiz fikri oku ve her birini kendi kelimelerinle söyle.","fa":"قبل از سؤال ۱۵، هشت ایده را بخوان و هر کدام را با کلمه‌های خودت بگو."},{"en":"Listen for each place name, then for the fact about it: when it was built, where it came from, who paid.","tr":"Her yerin adını, sonra onunla ilgili bilgiyi dinle: ne zaman yapıldı, nereden geldi, kim ödedi.","fa":"منتظر اسم هر مکان باش و بعد اطلاعات مربوط به آن: کی ساخته شد، از کجا آمد، چه کسی پولش را داد."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Two extra ideas in the box","tr":"Kutuda iki fazla fikir","fa":"دو ایده‌ی اضافه در کادر"},"body":{"en":"Eight ideas, six places: two ideas are never the answer, and one place can sound like it fits two ideas. Choose the idea the guide states, not the one you imagine.","tr":"Sekiz fikir, altı yer: iki fikir hiçbir zaman cevap değildir ve bir yer iki fikre uyuyormuş gibi gelebilir. Hayal ettiğin fikri değil, rehberin söylediğini seç.","fa":"هشت ایده، شش مکان: دو ایده هیچ‌وقت جواب نیستند و ممکن است به نظر برسد یک مکان با دو ایده جور است. ایده‌ای را انتخاب کن که راهنما می‌گوید، نه آنچه خودت تصور می‌کنی."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One pair, step by step","tr":"Bir çift, adım adım","fa":"یک جفت سؤال، قدم به قدم"},"instruction":"Choose TWO letters, A-E.","item":"Which TWO things can visitors do at the castle? A climb the tower  B visit the kitchens  C have a picnic in the garden  D feed the swans  E hire an audio guide","lines":[["Guide","The tower is closed for repairs this year, I’m afraid. You can explore the old kitchens, though. Picnics are fine anywhere in the garden, but please don’t feed the swans. We used to have audio guides, but not any more."]],"answer":"B, C","walk":[{"en":"The question asks what visitors CAN do.","tr":"Soru ziyaretçilerin NE YAPABİLECEĞİNİ soruyor.","fa":"سؤال می‌پرسد بازدیدکننده‌ها چه کارهایی می‌توانند بکنند."},{"en":"Cross out A (\"closed\"), D (\"please don’t\") and E (\"not any more\").","tr":"A’yı (\"kapalı\"), D’yi (\"lütfen yapmayın\") ve E’yi (\"artık yok\") çiz.","fa":"A («بسته است»)، D («لطفاً این کار را نکنید») و E («دیگر نیست») را خط بزن."},{"en":"B and C are both allowed: the kitchens and picnics.","tr":"B ve C’ye izin var: mutfaklar ve piknik.","fa":"B و C هر دو مجازند: آشپزخانه‌ها و پیک‌نیک."}]},"quick":{"prompt":"\"Most people expect the bridge to be the oldest thing in the village, but the well beside the church is three hundred years older.\" What is the oldest thing in the village?","options":["the bridge","the church","the well"],"correct":2,"why":{"en":"The bridge is what people expect; \"but\" brings the fact: the well is older.","tr":"Köprü insanların beklediği şey; \"but\" gerçeği getiriyor: kuyu daha eski.","fa":"پل چیزی است که مردم انتظار دارند؛ «but» واقعیت را می‌آورد: چاه قدیمی‌تر است."}},"remember":{"en":"Choose what is confirmed for this visit, and match each place to the one fact the guide states.","tr":"Bu ziyaret için doğrulananı seç ve her yeri rehberin söylediği tek bilgiyle eşleştir.","fa":"چیزی را انتخاب کن که برای همین بازدید تأیید می‌شود و هر مکان را با تنها نکته‌ای که راهنما می‌گوید جور کن."},"type":"explain","id":"c-x08-l2-e","course":"ielts-exams","exam":"exam-08","unit":"x08-l2"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 2","title":{"en":"A tour of Ashcombe Road","tr":"Ashcombe Road turu","fa":"تور اشکام رود"},"timed":7,"ctx":["L2-tours"],"script":[{"who":"Guide","line":"Good morning, everyone, and welcome to Ashcombe Road, home of county cricket in this part of the world for over a hundred and fifty years. My name's Dafydd, and I'll be your guide for the next hour and a quarter. Before we set off, let me tell you a little about what's ahead."},{"who":"Guide","line":"We'll start here in the main stand and then walk round the edge of the ground. I know some of you were hoping to walk out onto the pitch itself, but I'm afraid that's not possible during the season, because the ground staff are preparing it for Saturday's match. What we can do, though, is go behind the scenes into the dressing rooms, where the players change and wait to bat. That's the part most visitors remember. And for the younger ones, there's a quiz sheet with twelve questions about the things you'll see on the way. Everyone who gets them all right wins a badge at the end."},{"who":"Guide","line":"A couple of practical things. The whole route is step-free, apart from the old scorers' box, which you can look at from outside. And you're welcome to take photos anywhere except in the dressing rooms, because players leave personal things in there. The tour doesn't go into the museum, by the way. Your ticket gives you entry to it, but it's a separate visit, and you can go in any time before four o'clock."},{"who":"Guide","line":"Now, quite a few people ask me about coming back to watch a match. For county games, children under twelve get in free with a paying adult, which makes it a very cheap family day out. People sometimes think members can bring a friend in for nothing, but that stopped a few years ago; guests now pay the normal price. Tickets for the big international match in July sell very quickly, but they don't go on sale until March, so there's no point looking yet. And unlike some grounds, we're happy for you to bring your own food and drink in, as long as it isn't in glass bottles."},{"who":"Guide","line":"Right, let's begin with a bit of history as we walk. The first building you can see on your left is the pavilion, the grand building with the balcony. This is where the club officials and the players have always watched the game. It's actually the oldest part of the ground. Everything else has been rebuilt at least once, but the pavilion is the same building that stood here when the first match was played."},{"who":"Guide","line":"Opposite it, at the far end, you'll see the scoreboard. In its day it was quite famous. When it was put up, it was the first scoreboard in the country to show the name of the batsman as well as the score, and within ten years most other county grounds had built one just like it."},{"who":"Guide","line":"Just here, by the boundary rope, is the heavy roller. Ground staff once used it to flatten the pitch, and it took a horse and four men to pull it. Today, of course, the work is done by a small machine, so the roller just stands here as a reminder of the old days. Children love climbing on it, but please don't let them, because the edges are sharp."},{"who":"Guide","line":"If you look up above the main entrance, there's the clock. It hasn't always been here. It originally hung on the front of the town's railway station, and when the station was rebuilt in the nineteen-sixties, the club bought it and brought it here. It still keeps very good time."},{"who":"Guide","line":"We're now passing the members' gate, with its iron arch. In the nineteen-twenties the club was nearly bankrupt, and it was the people of the town who saved it. Hundreds of families gave a few shillings each, and the money that was left over after the debts were paid went on this gate. You can see some of their names on the small plaques along the wall."},{"who":"Guide","line":"And finally, beyond that wall, is the practice ground, which everyone here calls the nursery. Young players train there, and on Saturdays it's open to local schools. A few years ago a terrible storm brought down two big trees across it, and the nets were destroyed. It took the whole winter to repair, but it's back in use now, as you can probably hear."},{"who":"Guide","line":"OK, let's go through this door and up the stairs to the dressing rooms. Please stay together, and mind the step at the top."}],"groups":[{"instruction":"Questions 11-12. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":11,"n2":12,"kind":"mcq2","prompt":"Which TWO things will visitors do on the tour?","options":["A walk out onto the pitch","B see where the players change","C look round the museum","D take photos of the players","E answer questions on a quiz sheet"],"correct":[1,4],"evidence":"go behind the scenes into the dressing rooms","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"B \"behind the scenes into the dressing rooms\" and E the children’s quiz sheet. The pitch is \"not possible\", the museum is \"a separate visit\", and photos are not allowed in the dressing rooms.","tr":"B \"perde arkasına, soyunma odalarına\" ve E çocukların bilgi yarışması kâğıdı. Sahaya çıkmak \"mümkün değil\", müze \"ayrı bir ziyaret\", soyunma odalarında fotoğraf yasak.","fa":"B «پشت صحنه، به رختکن‌ها» و E برگه‌ی مسابقه‌ی بچه‌ها. رفتن روی زمین «ممکن نیست»، موزه «بازدیدی جداست» و عکس گرفتن در رختکن مجاز نیست."}}]},{"instruction":"Questions 13-14. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":13,"n2":14,"kind":"mcq2","prompt":"Which TWO things does the guide say about watching a match at the ground?","options":["A Children under twelve do not pay for county matches.","B Members can bring a guest for free.","C Tickets for the July international are on sale now.","D Visitors may bring their own food.","E Drinks are only sold in glass bottles."],"correct":[0,3],"evidence":"children under twelve get in free with a paying adult","trap":["TR-ruledout"],"why":{"en":"A \"under twelve get in free\" and D \"happy for you to bring your own food and drink\". Free guests \"stopped a few years ago\", and July tickets go on sale \"not until March\".","tr":"A \"on iki yaş altı ücretsiz girer\" ve D \"kendi yiyecek ve içeceğinizi getirebilirsiniz\". Ücretsiz misafir \"birkaç yıl önce kalktı\", temmuz biletleri \"marttan önce\" satışta değil.","fa":"A «زیر دوازده سال رایگان وارد می‌شوند» و D «خوشحال می‌شویم غذا و نوشیدنی خودتان را بیاورید». مهمان رایگان «چند سال پیش تمام شد» و بلیت‌های ژوئیه «تا مارس» فروخته نمی‌شوند."}}]},{"instruction":"Questions 15-20. What does the guide say about each of the following parts of the ground? Choose SIX answers from the box and write the correct letter, A-H, next to Questions 15-20.","qtype":"matching","bank":["A It was paid for by local people.","B It was badly damaged by the weather.","C It came from another building in the town.","D It was built before anything else there.","E It was designed by a former player.","F It is no longer used for its original purpose.","G It is closed to the public.","H Other grounds built one like it."],"questions":[{"n":15,"kind":"match","prompt":"the pavilion","correct":3,"evidence":"It's actually the oldest part of the ground","why":{"en":"\"Everything else has been rebuilt at least once\": the pavilion is the oldest part.","tr":"\"Diğer her şey en az bir kez yeniden yapıldı\": en eski bölüm pavyon.","fa":"«بقیه‌ی همه‌چیز دست‌کم یک بار بازسازی شده»: پاویون قدیمی‌ترین بخش است."},"trap":["TR-paraphrase"]},{"n":16,"kind":"match","prompt":"the scoreboard","correct":7,"evidence":"most other county grounds had built one just like it","why":{"en":"\"Most other county grounds had built one just like it\" = other grounds copied it.","tr":"\"Diğer kontluk sahalarının çoğu aynısından yaptı\" = diğer sahalar onu örnek aldı.","fa":"«بیشترِ زمین‌های دیگر یکی درست مثل آن ساختند» یعنی زمین‌های دیگر از رویش ساختند."},"trap":["TR-paraphrase"]},{"n":17,"kind":"match","prompt":"the heavy roller","correct":5,"evidence":"the roller just stands here as a reminder of the old days","why":{"en":"A machine does the work now; the roller \"just stands here\" = no longer used.","tr":"Artık işi bir makine yapıyor; silindir \"sadece burada duruyor\" = artık kullanılmıyor.","fa":"حالا کار را یک دستگاه انجام می‌دهد؛ غلتک «فقط این‌جا ایستاده» یعنی دیگر استفاده نمی‌شود."},"trap":["TR-paraphrase","TR-ruledout"]},{"n":18,"kind":"match","prompt":"the clock","correct":2,"evidence":"It originally hung on the front of the town's railway station","why":{"en":"\"It originally hung on the front of the town’s railway station\" = it came from another building.","tr":"\"Aslen kasabanın tren istasyonunun önünde asılıydı\" = başka bir binadan geldi.","fa":"«در اصل روی نمای ایستگاه قطار شهر آویزان بود» یعنی از ساختمان دیگری آمده."},"trap":["TR-paraphrase"]},{"n":19,"kind":"match","prompt":"the members’ gate","correct":0,"evidence":"the money that was left over after the debts were paid went on this gate","why":{"en":"Families of the town gave money, and what was left over paid for the gate.","tr":"Kasabanın aileleri para verdi; artan para kapıya harcandı.","fa":"خانواده‌های شهر پول دادند و پولی که ماند خرج دروازه شد."},"trap":["TR-paraphrase"]},{"n":20,"kind":"match","prompt":"the practice ground","correct":1,"evidence":"A few years ago a terrible storm brought down two big trees","why":{"en":"A storm brought down two trees and destroyed the nets = badly damaged by the weather. It is open to schools, so G is wrong.","tr":"Bir fırtına iki ağacı devirdi, fileleri yok etti = hava yüzünden ağır hasar. Okullara açık, yani G yanlış.","fa":"طوفان دو درخت را انداخت و تورها را نابود کرد، یعنی آسیب شدید به‌خاطر هوا. به روی مدرسه‌ها باز است، پس G غلط است."},"trap":["TR-paraphrase","TR-ruledout"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Guide":{"accent":"Northern English","gender":"M","tts":{"engine":"piper","voice":"en_GB-northern_english_male-medium"},"role":"Tour guide at a cricket ground"}},"sequence":[{"type":"announcer","text":"Part 2. You will hear a guide talking to a group of visitors at a cricket ground. First, you have some time to look at Questions 11 to 14."},{"type":"pause","seconds":30,"note":"reading time, Questions 11-14"},{"type":"announcer","text":"Now listen carefully and answer Questions 11 to 14."},{"type":"sfx","note":"outdoors: light wind, distant birds, a few people murmuring"},{"type":"lines","from":0,"to":3},{"type":"announcer","text":"Before you hear the rest of the talk, you have some time to look at Questions 15 to 20."},{"type":"pause","seconds":30,"note":"reading time, Questions 15-20"},{"type":"announcer","text":"Now listen and answer Questions 15 to 20."},{"type":"lines","from":4,"to":10,"note":"footsteps between paragraphs; in paragraph 10 the faint sound of a ball being hit"},{"type":"announcer","text":"That is the end of Part 2. You now have half a minute to check your answers.","after":30}]},"id":"c-x08-l2-d","course":"ielts-exams","exam":"exam-08","unit":"x08-l2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"A guide says the route is \"step-free\". This means...","options":["the tour costs nothing","there are no stairs on the way","you can walk at your own speed"],"correct":1,"why":{"en":"Step-free = no steps or stairs, so wheelchairs and buggies can use it.","tr":"Step-free = basamak ya da merdiven yok; tekerlekli sandalye ve bebek arabası geçebilir.","fa":"step-free یعنی بدون پله، پس ویلچر و کالسکه هم می‌توانند بروند."}},{"tests":"paraphrase","point":3,"prompt":"Box: \"It is no longer used for its original purpose.\" Which sentence in a talk matches it?","options":["These days it’s just there for decoration.","It’s been repainted several times.","It was moved here in 1950."],"correct":0,"why":{"en":"\"Just there for decoration\" = it no longer does its old job.","tr":"\"Sadece süs için orada\" = artık eski işini yapmıyor.","fa":"«فقط برای تزئین آن‌جاست» یعنی دیگر کار قبلی‌اش را نمی‌کند."}},{"tests":"trap","point":1,"prompt":"\"Lots of people ask if they can go up the tower. Normally, yes, but it’s closed this month.\" Can visitors on today’s tour go up the tower?","options":["Yes","Only with a guide","No"],"correct":2,"why":{"en":"\"Normally, yes\" is the distractor; \"closed this month\" is the fact for today.","tr":"\"Normalde evet\" çeldirici; \"bu ay kapalı\" bugün için gerçek.","fa":"«معمولاً بله» گزینه‌ی انحرافی است؛ «این ماه بسته است» واقعیتِ امروز است."}},{"tests":"method","point":2,"prompt":"You chose B and D for Questions 13-14, but then you hear option D ruled out. What do you do?","options":["Keep D because you heard it first","Change D and keep listening for a second answer","Leave both answers blank"],"correct":1,"why":{"en":"An option can be ruled out later in the same point. Change your answer while the talk is still on that topic.","tr":"Bir seçenek aynı konunun ilerleyen kısmında elenebilir. Konuşma hâlâ o konudayken cevabını değiştir.","fa":"ممکن است گزینه‌ای کمی بعد در همان موضوع رد شود. تا وقتی صحبت هنوز درباره‌ی همان موضوع است، جوابت را عوض کن."}},{"tests":"method","point":2,"prompt":"Questions 15-20 have six places and eight letters. How many letters will you NOT use?","options":["two","none","six"],"correct":0,"why":{"en":"Six answers from eight letters: two letters are left over.","tr":"Sekiz harften altı cevap: iki harf artar.","fa":"شش جواب از هشت حرف: دو حرف اضافه می‌ماند."}}],"id":"c-x08-l2-x","course":"ielts-exams","exam":"exam-08","unit":"x08-l2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
